// lib-email-provider - validate the request. Fail fast, provider-agnostic.
const items = $input.all();
if (items.length > 1) throw new Error('lib-email-provider: expects exactly one input item, got ' + items.length);
const inp = (items[0] && items[0].json) || {};
const mode = inp.mode;
if (!['message', 'thread', 'list', 'report_spam'].includes(mode)) throw new Error(`lib-email-provider: bad or missing mode '${mode}' (must be 'message', 'thread', 'list', or 'report_spam')`);
const ref = inp.source_ref || {};
// Ids are URL path segments: restrict to the provider id alphabet so a crafted
// reference cannot rewrite the request path/query (by-reference boundary).
const ID_RE = /^[A-Za-z0-9_-]+$/;
if ((mode === 'message' || mode === 'report_spam') && !ID_RE.test(String(ref.uuid ?? ''))) throw new Error(`lib-email-provider: mode "${mode}" requires source_ref.uuid (non-empty, [A-Za-z0-9_-] only)`);
// list mode: scope_query is a Gmail search string, required non-empty.
if (mode === 'list' && (typeof inp.scope_query !== 'string' || inp.scope_query.trim() === '')) throw new Error('lib-email-provider: mode "list" requires scope_query (non-empty Gmail search string)');
if (mode === 'thread' && !ID_RE.test(String(ref.conversation_id ?? ''))) throw new Error('lib-email-provider: mode "thread" requires source_ref.conversation_id (non-empty, [A-Za-z0-9_-] only)');
if (inp.include_attachments !== undefined && typeof inp.include_attachments !== 'boolean') throw new Error('lib-email-provider: include_attachments must be boolean when present, got ' + JSON.stringify(inp.include_attachments));
// Optional pre-download ceiling: over-cap or unknown-size
// attachments are skipped BEFORE the bytes transit Gmail + Code-node memory.
if (inp.max_attachment_bytes !== undefined && (typeof inp.max_attachment_bytes !== 'number' || !Number.isFinite(inp.max_attachment_bytes) || inp.max_attachment_bytes <= 0)) throw new Error('lib-email-provider: max_attachment_bytes must be a positive number when present, got ' + JSON.stringify(inp.max_attachment_bytes));
return [{ json: { ...inp, source_ref: ref, include_attachments: inp.include_attachments === true, max_attachment_bytes: inp.max_attachment_bytes ?? null } }];

const mode = $input.first().json.mode;
throw new Error(`lib-email-provider: unmatched mode '${mode}' - validation and Switch routing have drifted`);
return [];

// Normalize (raw Gmail REST -> canonical messages[]). The ONLY Gmail-shape-aware
// code: the provider swap point.
const req = $('When Called (source ref + mode)').first().json;
const includeAttachments = req.include_attachments === true;
const capBytes = (typeof req.max_attachment_bytes === 'number' && req.max_attachment_bytes > 0) ? req.max_attachment_bytes : null;   // pre-download ceiling
const mode = req.mode;

// HTTP node runs with fullResponse+neverError: unwrap the body and map provider
// failures to the lib's provider-agnostic error contract.
function httpBody(resp, what) {
  const r = resp || {};
  if (r.statusCode === undefined) return r; // defensive: plain body shape
  const s = r.statusCode;
  if (s >= 200 && s < 300) return r.body || {};
  if (s === 404) throw new Error('lib-email-provider: ' + what + ' not found for the given reference');
  if (s === 401 || s === 403) throw new Error('lib-email-provider: provider auth failed (' + s + ') - check the shared email credential');
  if (s === 429) throw new Error('lib-email-provider: provider rate limit hit - retry later');
  throw new Error('lib-email-provider: provider fetch failed (' + s + ')');
}
function headerMap(payload) {
  const m = {};
  const hs = (payload && Array.isArray(payload.headers)) ? payload.headers : [];
  for (const h of hs) { if (h && h.name) m[h.name.toLowerCase()] = h.value; }
  return m;
}
function headerAll(payload, name) {
  const hs = (payload && Array.isArray(payload.headers)) ? payload.headers : [];
  return hs.filter(h => h && h.name && h.name.toLowerCase() === name).map(h => String(h.value || ''));
}
function charsetOf(part) {
  const hs = (part && Array.isArray(part.headers)) ? part.headers : [];
  for (const h of hs) {
    if (h && h.name && h.name.toLowerCase() === 'content-type') {
      const m = /charset\s*=\s*"?([\w.:-]+)"?/i.exec(String(h.value || ''));
      if (m) return m[1].toLowerCase();
    }
  }
  return '';
}
function decode(data, charset) {
  if (!data) return '';
  try {
    const buf = Buffer.from(String(data).replace(/-/g, '+').replace(/_/g, '/'), 'base64');
    const cs = (charset || 'utf-8').toLowerCase();
    if (['utf-8', 'utf8', 'us-ascii', 'ascii'].includes(cs)) return buf.toString('utf-8');
    if (typeof TextDecoder !== 'undefined') { try { return new TextDecoder(cs).decode(buf); } catch (e) { /* unknown label - fall through */ } }
    if (['iso-8859-1', 'latin1', 'windows-1252', 'cp1252'].includes(cs)) return buf.toString('latin1');
    return buf.toString('utf-8');
  } catch (e) { return ''; }
}
function dispositionOf(part) {
  const hs = (part && Array.isArray(part.headers)) ? part.headers : [];
  let disp = '', cid = '';
  for (const h of hs) {
    if (!h || !h.name) continue;
    const n = h.name.toLowerCase();
    if (n === 'content-disposition') disp = String(h.value || '').toLowerCase();
    else if (n === 'content-id') cid = String(h.value || '');
  }
  // An explicit `attachment` disposition WINS over a
  // Content-ID — Gmail attaches cid headers to real attachments on forwards,
  // which made the 1.4 heuristic (`inline-disposition OR cid`) misclassify
  // them as inline (live-caught on fixture 19f019f83c19f815).
  const isAttachment = disp.startsWith('attachment');
  return { isAttachment, isInline: !isAttachment && (disp.startsWith('inline') || !!cid) };
}
function walk(part, acc) {
  if (!part) return;
  const mime = (part.mimeType || '').toLowerCase();
  const body = part.body || {};
  const d = dispositionOf(part);
  if (body.attachmentId) {
    // Presence keys on attachmentId (a filename-less part is still an attachment);
    // is_inline lets the bridge filter embedded signature images from surface-or-flag.
    acc.attachments.push({ filename: part.filename || '', mime_type: part.mimeType || '', size: (body.size === undefined ? null : body.size), attachment_id: body.attachmentId, is_inline: d.isInline });
    // A body-role text part delivered by reference only: signal, don't return '' silently.
    if ((mime === 'text/plain' || mime === 'text/html') && !d.isAttachment && !body.data) acc.body_truncated = true;
  } else if (mime === 'text/plain' && body.data && !d.isAttachment && !acc.body_text) {
    acc.body_text = decode(body.data, charsetOf(part));
  } else if (mime === 'text/html' && body.data && !d.isAttachment && !acc.body_html) {
    acc.body_html = decode(body.data, charsetOf(part));
  }
  if (mime === 'message/rfc822') return; // a forwarded message's body must not win the outer slots
  if (Array.isArray(part.parts)) for (const p of part.parts) walk(p, acc);
}
function normalizeOne(msg) {
  const acc = { body_text: '', body_html: '', attachments: [], body_truncated: false };
  const payload = msg.payload;
  const hdr = headerMap(payload);
  if (payload) {
    walk(payload, acc);
    if (!acc.body_text && !acc.body_html && payload.body && payload.body.data) {
      const d = decode(payload.body.data, charsetOf(payload));
      if ((payload.mimeType || '').includes('html')) acc.body_html = d; else acc.body_text = d;
    }
  }
  let date = null;
  if (msg.internalDate) date = new Date(Number(msg.internalDate)).toISOString();
  else { const t = Date.parse(hdr['date'] || ''); if (!Number.isNaN(t)) date = new Date(t).toISOString(); }
  return {
    uuid: msg.id,
    conversation_id: msg.threadId,
    from: hdr['from'] || '',
    to: hdr['to'] || '',
    cc: hdr['cc'] || '',
    subject: hdr['subject'] || '',
    // Unsubscribe facts (RFC 8058) — reported, never decided here. headerMap keeps
    // the LAST header of a name; these are collected in order (Gmail prepends its
    // own Authentication-Results, so index 0 is Gmail's verdict).
    list_unsubscribe: hdr['list-unsubscribe'] || '',
    list_unsubscribe_post: hdr['list-unsubscribe-post'] || '',
    authentication_results: headerAll(payload, 'authentication-results'),
    dkim_signatures: headerAll(payload, 'dkim-signature'),
    date,
    snippet: msg.snippet || '',
    body_text: acc.body_text,
    body_html: acc.body_html,
    body_truncated: acc.body_truncated,
    has_attachments: acc.attachments.length > 0,
    attachments: acc.attachments,
  };
}let messages;
if (mode === 'message') {
  messages = [normalizeOne(httpBody($input.first().json, 'message'))];
} else {
  const top = httpBody($input.first().json, 'thread');
  if (!Array.isArray(top.messages) || top.messages.length === 0) {
    throw new Error('lib-email-provider: thread fetch returned no messages for the given reference');
  }
  // oldest -> newest; fall back to the RFC2822 Date header when internalDate is absent.
  function sortKey(msg) {
    if (msg.internalDate) return Number(msg.internalDate);
    const hs = (msg.payload && Array.isArray(msg.payload.headers)) ? msg.payload.headers : [];
    const dh = hs.find(h => h && h.name && h.name.toLowerCase() === 'date');
    const t = dh ? Date.parse(String(dh.value || '')) : NaN;
    return Number.isNaN(t) ? 0 : t;
  }
  messages = top.messages.slice().sort((a, b) => sortKey(a) - sortKey(b)).map(m => normalizeOne(m));
}

// include_attachments:true -> plan REAL byte downloads. Non-inline parts only: inline parts (signature images
// etc.) stay metadata-only, marked bytes_skipped:'inline'.
const downloads = [];
if (includeAttachments) {
  messages.forEach((m, mi) => m.attachments.forEach((a, ai) => {
    if (a.is_inline) { a.bytes_skipped = 'inline'; return; }
    if (capBytes != null && a.size != null && a.size > capBytes) { a.bytes_skipped = 'size ' + a.size + ' B exceeds max_attachment_bytes ' + capBytes + ' — not downloaded'; return; }
    if (capBytes != null && a.size == null) { a.bytes_skipped = 'size unknown — not downloaded while max_attachment_bytes is set'; return; }
    downloads.push({ message_uuid: m.uuid, attachment_id: a.attachment_id,
      binary_key: 'att_' + downloads.length, filename: a.filename || ('attachment-' + downloads.length),
      mime_type: a.mime_type || 'application/octet-stream', size: a.size, msg_index: mi, att_index: ai });
  }));
}
return [{ json: { kind: 'email', mode, source_ref: req.source_ref || {}, messages, __downloads: downloads } }];

// base64url -> base64 binary items (1.5 Finding #5 topology, steps 3-4).
// Per-attachment failure is NON-fatal: metadata keeps flowing with bytes_error
// so the caller's flag-with-pointer path can take over.
const env = JSON.parse(JSON.stringify($('Normalize response').first().json));
const plans = $('List downloads').all().map(i => i.json);
const resps = $input.all().map(i => i.json);
const binary = {};
plans.forEach((d, i) => {
  const r = resps[i] || {};
  const att = env.messages[d.msg_index].attachments[d.att_index];
  if (r.statusCode === 200 && r.body && r.body.data) {
    binary[d.binary_key] = { data: String(r.body.data).replace(/-/g, '+').replace(/_/g, '/'),
      mimeType: d.mime_type, fileName: d.filename };
    att.binary_key = d.binary_key;
  } else {
    att.bytes_error = 'download failed (' + (r.statusCode ?? (r.error ? 'connection error: ' + String((r.error && r.error.message) ?? r.error).slice(0, 120) : 'no response')) + ')';
  }
});
return [{ json: env, binary }];

// Single terminal keeps the sub-workflow's output deterministic on both branches.
const it = $input.first();
const j = { ...it.json };
delete j.__downloads;
return [{ json: j, binary: it.binary ?? {} }];

// list mode -> refs-ONLY envelope. Deliberately BYPASSES
// `Normalize response` and the download branch: list never fetches content, so
// references-only holds on the wire. This is the only list-shape-aware code.
const req = $('When Called (source ref + mode)').first().json;
const pages = $input.all().map(i => i.json);
function pageBody(r) {
  // Connection-level failure (DNS/refused/timeout): the HTTP node runs with
  // onError:continueRegularOutput (1.7 review P1 - same class 1.6 fixed on the
  // download node), so transport failures arrive as error items - re-throw
  // with the provider prefix instead of leaking a raw axios error.
  if (r && r.error !== undefined && r.statusCode === undefined) throw new Error('lib-email-provider: list request failed before a response (connection/transport): ' + String(r.error && r.error.message ? r.error.message : r.error).slice(0, 200));
  // A page we cannot read is NOT an empty page - fail loud (1.7 review P3).
  if (!r || typeof r !== 'object' || r.statusCode === undefined) throw new Error('lib-email-provider: unexpected list response shape (no statusCode) - refusing to treat as an empty page');
  const s = r.statusCode;
  if (s >= 200 && s < 300) {
    const b = r.body;
    if (!b || typeof b !== 'object' || Array.isArray(b)) throw new Error('lib-email-provider: list page body is not a JSON object - refusing to treat as an empty page');
    return b;
  }
  if (s === 400) throw new Error('lib-email-provider: provider rejected the list query (400) - check scope_query syntax');
  if (s === 401 || s === 403) throw new Error('lib-email-provider: provider auth failed (' + s + ') - check the shared email credential');
  if (s === 429) throw new Error('lib-email-provider: provider rate limit hit - retry later');
  throw new Error('lib-email-provider: provider list failed (' + s + ')');
}
const bodies = pages.map(pageBody);
// Hard cap hit = a dangling nextPageToken after the last fetched page: that
// many ids in one poll window means something is wrong upstream - fail loud.
if (bodies.length && bodies[bodies.length - 1].nextPageToken) throw new Error('lib-email-provider: list pagination cap hit (' + bodies.length + ' pages fetched, more remain) - refusing to silently truncate; narrow scope_query');
const ID_RE = /^[A-Za-z0-9_-]+$/;
const messages = [];
let dropped = 0;
for (const b of bodies) {
  // Gmail gotcha: an empty result OMITS the `messages` key entirely - normalize
  // to [], never throw (callers ALWAYS read messages[]).
  for (const m of (Array.isArray(b.messages) ? b.messages : [])) {
    // Output ids re-validated against the provider id alphabet BEFORE any caller
    // can put them in SQL/URLs (the input guard covers inputs, not Gmail output).
    if (ID_RE.test(String(m.id ?? '')) && ID_RE.test(String(m.threadId ?? ''))) {
      messages.push({ uuid: m.id, conversation_id: m.threadId });
    } else {
      dropped++;
      console.log('lib-email-provider: list dropped out-of-alphabet entry: ' + JSON.stringify(m).slice(0, 200));
    }
  }
}
if (dropped) console.log('lib-email-provider: list dropped ' + dropped + ' malformed entries this poll');
// Every entry dropped = systematic id-shape breach (provider swap / format
// change), NOT an empty inbox - fail loud instead of a silent green no-op
// (1.7 review P2). `dropped` rides the envelope so partial drops show up in
// execution data, not only worker stdout.
if (dropped && messages.length === 0) throw new Error('lib-email-provider: list dropped ALL ' + dropped + ' entries as out-of-alphabet - id shape breach, refusing to return an empty envelope');
return [{ json: { kind: 'email', mode: 'list', source_ref: { scope_query: req.scope_query }, messages, dropped } }];

// report_spam: the one write this provider performs. Same status mapping as
// Normalize's httpBody(); the envelope carries ok + the labels Gmail reports.
const req = $('When Called (source ref + mode)').first().json;
const r = $input.first().json || {};
const s = r.statusCode;
let body = r;
if (s !== undefined) {
  if (s === 404) throw new Error('lib-email-provider: message not found for the given reference');
  if (s === 401 || s === 403) throw new Error('lib-email-provider: provider auth failed (' + s + ') - check the shared email credential');
  if (s === 429) throw new Error('lib-email-provider: provider rate limit hit - retry later');
  if (s < 200 || s >= 300) throw new Error('lib-email-provider: report_spam failed (' + s + ')');
  body = r.body || {};
}
return [{ json: { kind: 'email', mode: 'report_spam', source_ref: req.source_ref || {}, ok: true, label_ids: body.labelIds || [] } }];
